-- Passage rg3-argument-evidence-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('09726f58-fc64-5103-a671-8479e5099902', 'rg3-argument-evidence-p04', (select id from public.skills where slug = 'read-g3-argument-evidence'), null,
        '3-5', $q$Every Classroom Needs a Reading Corner$q$, $q$I think every classroom in our school should have a reading corner. A reading corner is a cozy spot with a rug, pillows and a shelf of books. I have three reasons for my opinion.

First, a reading corner helps students find books they like. When books sit right in the room, students can look at them every day. In my class, we have a corner, and I have found five new favorite books this year.

Second, a quiet corner gives students a calm place to read. Some students have a hard time reading at a busy desk. In a soft, quiet spot, they can focus on the story.

Third, a reading corner does not cost much. Families can give books they no longer need. Pillows and rugs can come from the school's lost and found closet if no one claims them.

For these reasons, I believe every classroom should have a reading corner. Let's ask our principal to help us build one in each room!$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
