-- Passage rg3-argument-evidence-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('90a72bfa-0f97-5954-902f-4462d97e736a', 'rg3-argument-evidence-p05', (select id from public.skills where slug = 'read-g3-argument-evidence'), null,
        '3-5', $q$The Light on Gull Point$q$, $q$Long ago, ships sailing near Gull Point had a big problem. Sharp rocks lay hidden under the water close to shore. At night, sailors could not see them. Many ships crashed into the rocks.

To solve this problem, the people of the nearby town built a lighthouse on the point. It was a tall stone tower with a bright lamp at the top. Because the light shone far out over the sea, sailors could see it from miles away. The light warned them to steer away from the rocks.

A keeper named Ezra Odum lived in a small house beside the tower. Each evening, Ezra climbed the winding stairs. Then Ezra filled the lamp with oil and lit the wick. All night, Ezra wiped soot from the glass so the light would stay bright.

On foggy nights, the light was hard to see. So the keeper also rang a loud bell. Sailors who could not see the light could still hear the bell.

Today, the lamp at Gull Point turns on by itself. No keeper climbs the stairs anymore. Still, the light shines every night, and ships pass the rocks safely.$q$, 'draft')
