-- Passage rg3-connections-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('cdd4d8f1-7cbc-52de-aae3-c9425148fae1', 'rg3-connections-p06', (select id from public.skills where slug = 'read-g3-connections'), null,
        '3-5', $q$The Journey of a Can$q$, $q$When you drop an empty can into a recycling bin, its journey is just beginning. That can may come back to a store shelf in about two months.

First, a recycling truck picks up the bin and brings the cans to a large building. Workers and machines sort everything. A strong magnet pulls out steel cans. Aluminum cans do not stick to a magnet, so another machine pushes them into their own pile.

Next, the aluminum cans are crushed into big, flat blocks. Flat blocks take up less space, so a truck can carry many more of them. The blocks are taken to a factory.

At the factory, the cans are shredded into small pieces. The pieces are cleaned to remove paint and bits of food. Then they are melted in a very hot furnace. The melted metal is poured into long bars.

After the bars cool, machines roll them into thin sheets of metal. Other machines cut the sheets and shape them into new cans. The new cans are filled, sealed and shipped to stores.

Recycling a can uses much less energy than making a can from new metal dug out of the ground. That is one reason towns like Pinecrest ask families to recycle.$q$, 'draft')
