-- Passage rg3-figurative-language-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('c6967d60-8b99-53c0-a131-c6b65016e508', 'rg3-figurative-language-p01', (select id from public.skills where slug = 'read-g3-figurative-language'), null,
        '3-5', $q$The Big Pass$q$, $q$The score was tied, and there were only two minutes left. My stomach was full of butterflies. Coach Rivera waved at me from the sideline. "Take a deep breath," the coach called. "You can do this."

The ball rolled toward me, and I stopped it with my foot. A tall player from the other team raced over. I could hear my heart pounding like a drum. Then I looked up and saw my friend Tomas standing open near the goal.

I kicked the ball to Tomas. Tomas tapped it once and sent it flying past the goalie. The crowd went wild! Our whole team jumped up and down.

After the game, Tomas found me by the water fountain. "That pass was a gift," Tomas said. "I just had to open it." I laughed so hard that I almost dropped my water bottle.

On the bus ride home, I was still floating on air. I had not scored the goal, but I had helped my team. To me, that felt even better.$q$, 'draft')
