-- Passage rg3-figurative-language-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('e71dd2ff-cec2-5ebf-b21f-166acd536474', 'rg3-figurative-language-p05', (select id from public.skills where slug = 'read-g3-figurative-language'), null,
        '3-5', $q$The Missing Crown$q$, $q$The class play was only one day away. Ms. Okafor's third graders had practiced for weeks. Priya would play the queen, and Jun would play the royal cook.

During the last practice, Priya reached for the paper crown. It was not on the prop table! Priya's face fell. "Has anyone seen the crown?" Priya asked.

Jun looked under the chairs. Leo checked behind the curtain. Nobody could find it. Priya suspected that it had been thrown away by mistake, because the trash can was right next to the table.

Then Ms. Okafor smiled. "Don't worry. We can make a new one," she said. In a flash, the whole class grabbed paper, glue and glitter. Everyone pitched in. Some students cut out the points. Others added shiny paper jewels.

Ten minutes later, the new crown was ready. It was even better than the old one. Priya put it on and stood up tall. Jun clapped. "Now you really look like a queen," Jun said.

The next night, the play went off without a hitch. When the curtain closed, the audience clapped and clapped. Priya knew that the class had done something special together.$q$, 'draft')
